const Router = require('koa-router');
const router = new Router();

router.delete('/api/v2/invoices/:invoiceId/items/:itemId', authenticateKoa, async (ctx) => {
  const { invoiceId, itemId } = ctx.params;

  const invoice = await knex('invoices')
    .where({ id: invoiceId, organization_id: ctx.state.user.organizationId })
    .first();
  if (!invoice) {
    ctx.status = 403;
    ctx.body = { error: 'Forbidden: invoice does not belong to your organization' };
    return;
  }

  const deletedRows = await knex('invoice_items')
    .where({ id: itemId, invoice_id: invoiceId })
    .del();

  if (!deletedRows) {
    ctx.status = 404;
    ctx.body = { error: 'Invoice line item not found' };
    return;
  }

  ctx.status = 200;
  ctx.body = { success: true, removedItemId: itemId };
});
